function Report({risk}:{risk:Risk}){return <div className="risk-report"><div className={'risk-summary '+risk.level.toLowerCase()}><div className="risk-orb"><strong>{risk.score}</strong><small>/ 100</small></div><div><Badge tone={risk.level==='Low'?'green':risk.level==='Medium'?'amber':'red'}>{risk.level} risk</Badge><p>{risk.recommendation}</p></div></div><h4>Evidence behind this assessment</h4>{risk.evidence.map((e,i)=><div className="evidence" key={e.code+i}><div className={'evidence-icon '+(e.points?'amber':'green')}>{e.points?<AlertTriangle size={16}/>:<Check size={16}/>}</div><div><strong>{e.reason}</strong><small>{e.source==='confirmed'?'Confirmed threat intelligence':e.source==='observation'?'Observed in submitted records':e.source==='heuristic'?'Heuristic indicator':'Unknown / insufficient data'} · {e.points?`+${e.points} points`:'0 points'}</small></div></div>)}<p className="fine">Scores describe available evidence, not a guarantee of safety. AI does not invent evidence or authorize payments.</p></div>;}
function GlobeArt(){return <svg className="globe-art" viewBox="0 0 380 280" aria-hidden="true"><defs><radialGradient id="g"><stop stopColor="#a797ff" stopOpacity=".38"/><stop offset="1" stopColor="#8c71e9" stopOpacity="0"/></radialGradient><clipPath id="gc"><circle cx="208" cy="139" r="109"/></clipPath></defs><circle cx="208" cy="139" r="137" fill="url(#g)"/><g fill="none" stroke="#c8bbff" strokeWidth=".7" opacity=".35"><circle cx="208" cy="139" r="109"/>{[25,50,78,100].map(r=><ellipse key={r} cx="208" cy="139" rx={r} ry="109"/>)}<g clipPath="url(#gc)">{[60,85,110,139,167,194,219].map(y=><ellipse key={y} cx="208" cy={y} rx="109" ry="16"/>)}</g><path d="M72 196 Q188 -5 341 106" strokeDasharray="3 5"/><path d="M91 75 Q190 241 345 163" strokeDasharray="3 5"/></g><g fill="#e2d9ff">{[[124,92],[273,100],[228,190],[170,140]].map(([x,y])=><g key={x}><circle cx={x} cy={y} r="9" opacity=".15"/><circle cx={x} cy={y} r="3"/></g>)}</g><path d="M124 92 Q190 40 273 100 Q290 160 228 190" fill="none" stroke="#c9b8ff" strokeWidth="1.6"/><g transform="translate(96 196)"><rect width="90" height="28" rx="14" fill="#ffffff" fillOpacity=".13"/><text x="45" y="18" textAnchor="middle" fontSize="10" fill="white">↗ Borderless</text></g></svg>;}
