 const [signupName,setSignupName]=useState(''),[signupType,setSignupType]=useState<'customer'|'supplier'>('customer'),[checkOnboarding,setCheckOnboarding]=useState(false);
 const [confirmationEmail,setConfirmationEmail]=useState(''),[authMessage,setAuthMessage]=useState(''),[authMessageTone,setAuthMessageTone]=useState<'red'|'green'>('red'),[customRecipient,setCustomRecipient]=useState(false);
 const [recoveryGrant,setRecoveryGrant]=useState<RecoveryGrant|null>(null),[recoveryError,setRecoveryError]=useState(''),[recoveryChecking,setRecoveryChecking]=useState(initialPage==='auth/reset');
