 const [workspaceMode,setWorkspaceMode]=useState<WorkspaceMode>('demo'),[accountEmail,setAccountEmail]=useState(''),[authAvailable,setAuthAvailable]=useState<boolean|null>(null),[authSetupIssue,setAuthSetupIssue]=useState(''),[authRetry,setAuthRetry]=useState(0);
 const [selected,setSelected]=useState(''),[filter,setFilter]=useState('All invoices'),[invoiceText,setInvoiceText]=useState(''),[draft,setDraft]=useState<Invoice|null>(null),[ai,setAI]=useState(false),[uploadName,setUploadName]=useState(''),[message,setMessage]=useState(''),[assistantAI,setAssistantAI]=useState(false),[chat,setChat]=useState<{role:string;text:string;structured?:unknown;provider?:string}[]>([]);
 const [paymentForm,setPaymentForm]=useState({supplier:'',amount:'',asset:'USDC',recipient:'',chain:'base',invoiceId:''}),[paymentRisk,setPaymentRisk]=useState<Risk|null>(null),[confirmed,setConfirmed]=useState(false),[reviewed,setReviewed]=useState(false),[quoteTime,setQuoteTime]=useState(0),[quoteMode,setQuoteMode]=useState<'demo'|'live'>('demo');
 const [tokens,setTokens]=useState<Token[]>([]),[originAsset,setOriginAsset]=useState(''),[destAsset,setDestAsset]=useState(''),[sourceAmount,setSourceAmount]=useState(''),[refund,setRefund]=useState(''),[slippage,setSlippage]=useState('100'),[liveQuote,setLiveQuote]=useState<any>(null),[apiError,setApiError]=useState('');
 const [toolInput,setToolInput]=useState(''),[toolChain,setToolChain]=useState('base'),[toolResult,setToolResult]=useState<{risk:Risk;observation?:unknown}|null>(null),[statusAddress,setStatusAddress]=useState(''),[statusMemo,setStatusMemo]=useState(''),[liveStatus,setLiveStatus]=useState<any>(null),[authEmail,setAuthEmail]=useState(''),[authPassword,setAuthPassword]=useState(''),[authMode,setAuthMode]=useState('signin');
 const [supplierName,setSupplierName]=useState(''),[supplierWallet,setSupplierWallet]=useState(''),[supplierChain,setSupplierChain]=useState('base'),[supplierVerified,setSupplierVerified]=useState(false);
 const fileRef=useRef<HTMLInputElement>(null);
 const mainWallet=useWalletSession('mainnet',accountId),testWallet=useWalletSession('testnet',accountId);const wallet=mainWallet.connected?mainWallet.account:'';
 const previousWalletOwner=useRef<string|null|undefined>(undefined);useEffect(()=>{const previous=previousWalletOwner.current;if(previous!==undefined&&previous!==accountId)void disconnectWalletOwner(previous||'guest');previousWalletOwner.current=accountId;},[accountId]);
 const notify=(value:string)=>{setToast(value);};
 useEffect(()=>{const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t);},[toast]);
 useEffect(()=>{const pop=()=>setPage(location.pathname.slice(1)||'dashboard');window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
 useEffect(()=>{try{const saved=localStorage.getItem('afripay-view-mode');if(saved==='live'||saved==='demo'||saved==='testnet')setWorkspaceMode(saved);}catch{}},[]);
 useEffect(()=>{let active=true;let unsubscribe:(()=>void)|undefined;let timer:ReturnType<typeof setTimeout>|undefined;let revision=0;
  // Read the callback context before Supabase consumes and removes its URL fragment.
  const callback=recoveryCallback(location.href);
  if(callback.isRecovery){setPage('auth/reset');setRecoveryChecking(!callback.error);setRecoveryError(callback.error||'');}
  if(callback.error){const destination=callback.isRecovery?'auth/reset':'auth';history.replaceState({},'','/'+destination);setPage(destination);if(callback.isRecovery)setRecoveryError(callback.error);else{setAuthMessage(callback.error);setAuthMessageTone('red');}setRecoveryChecking(false);}
  async function startAuth(){try{const auth=await withDeadline(initializeAuth(),4500,'Account setup check timed out. Guest tools remain available; retry account setup to sign in.');if(!active)return;setAuthAvailable(true);setAuthSetupIssue('');if(auth){
   const {data}=auth.auth.onAuthStateChange((event,session)=>{if(!active)return;revision++;setAccountEmail(session?.user.email||'');setAccountId(session?.user.id||null);
    if(event==='PASSWORD_RECOVERY'&&session){setRecoveryGrant({userId:session.user.id,email:session.user.email,expiresAt:Math.min((session.expires_at||Date.now()/1000+600)*1000,Date.now()+600000)});setRecoveryError('');setRecoveryChecking(false);setAuthPassword('');setPage('auth/reset');history.replaceState({},'','/auth/reset');}
    else setRecoveryGrant(current=>current&&current.userId!==session?.user.id?null:current);
   });unsubscribe=()=>data.subscription.unsubscribe();
   const initialRevision=revision;
   withDeadline(auth.auth.getSession(),3000,'Account session check timed out.').then(({data,error})=>{if(!active)return;if(revision===initialRevision){setAccountEmail(data.session?.user.email||'');setAccountId(data.session?.user.id||null);}if(callback.isRecovery){if(error){setRecoveryError('This reset link could not be verified. Request a new link.');setRecoveryChecking(false);}else timer=setTimeout(()=>{if(active)setRecoveryChecking(false);},1000);}}).catch(()=>{if(active){if(revision===initialRevision)setAccountId(null);setRecoveryChecking(false);setRecoveryError('Unable to verify the reset session. Request a new link.');}});
  }else{setAccountId(null);setRecoveryChecking(false);if(callback.isRecovery)setRecoveryError('Account access is not configured.');}}catch(error){if(active){setAuthAvailable(false);setAuthSetupIssue((error as Error).message);setAccountId(null);setRecoveryChecking(false);}}}
  void startAuth();
  return()=>{active=false;unsubscribe?.();if(timer)clearTimeout(timer);};
 },[authRetry]);
 useEffect(()=>{setSelectedCreditSupplier('');setDraft(null);setInvoiceText('');setUploadName('');setChat([]);setSearch('');setToolResult(null);setPaymentRisk(null);setLiveQuote(null);setLiveStatus(null);setConfirmed(false);setReviewed(false);setSelected('');setPaymentForm({supplier:'',amount:'',asset:'USDC',recipient:'',chain:'base',invoiceId:''});setCustomRecipient(false);},[accountId]);
 useEffect(()=>{if(checkOnboarding&&accountId&&!accountProfile.loading){setCheckOnboarding(false);if(!accountProfile.profile?.onboarding_completed)go('onboarding');}},[checkOnboarding,accountId,accountProfile.loading,accountProfile.profile]);
 useEffect(()=>{if(!accountId||!ready||checkOnboarding||page==='onboarding')return;let task;try{task=takeGuestTask(sessionStorage);}catch{return;}if(!task)return;if(task.invoice){setDraft({...task.invoice,id:uid(),verified:false,status:'Needs review',risk:undefined});setInvoiceText(task.text);setData(d=>({...d,suppliers:[...d.suppliers,...task.suppliers.filter(item=>!d.suppliers.some(own=>own.name===item.name)).map(item=>({...item,trusted:false}))]}));go('invoices/upload');notify('Your guest invoice was preserved. Review it and verify the recipient again before saving to your account.');}else if(task.text){setInvoiceText(task.text);go('invoices/upload');notify('Your invoice text was preserved through sign-in.');}else go(task.returnTo);},[accountId,ready,checkOnboarding,page]);
 function changeMode(mode:WorkspaceMode){setWorkspaceMode(mode);try{localStorage.setItem('afripay-view-mode',mode);}catch{}go('dashboard');}
 function preserveGuestTask(){if(accountId!==null)return;try{const linked=['payments','payments/preview','routes','approval'].includes(page)?data.invoices.find(item=>item.id===paymentForm.invoiceId):null;const invoice=page.startsWith('invoices/')?(draft||current||null):(linked||null);saveGuestTask(sessionStorage,{createdAt:Date.now(),returnTo:page==='feedback'?'feedback':invoice||(page.startsWith('invoices/')&&invoiceText)?'invoices/upload':page==='near/checks'?'near/checks':(page==='demo/transfers'||page==='transfer')?'transfer':page==='receive'?'receive':page==='transactions'?'transactions':'dashboard',invoice,text:invoice?.text||(page.startsWith('invoices/')?invoiceText:''),suppliers:invoice?data.suppliers.filter(item=>item.name===invoice.supplier).slice(0,5):[]});}catch{}}
 function requireAccount(){if(accountId)return true;preserveGuestTask();notify('Sign in to approve demo payments or download files. Your current invoice will be preserved.');openAuth('signin');return false;}
 function openAuth(mode:'signin'|'signup'){preserveGuestTask();setAuthMode(mode);setConfirmationEmail('');setAuthMessage('');setAuthMessageTone('red');go('auth');}
 function go(next:string){setPage(next);setSidebar(false);setToolResult(null);setApiError('');history.pushState({},'',next==='dashboard'?'/':'/'+next);window.scrollTo({top:0,behavior:'smooth'});}
 function audit(action:string,detail:string){setData(d=>({...d,audits:[{id:uid(),at:new Date().toISOString(),action,detail,mode:'demo'},...d.audits]}));}
 function recordRisk(title:string,risk:Risk){setData(d=>({...d,events:[{id:uid(),title,risk,at:new Date().toISOString(),read:false},...d.events],audits:[{id:uid(),at:new Date().toISOString(),action:'Security analysis',detail:title,mode:'demo'},...d.audits]}));}
 async function request(url:string,body?:unknown){const token=body&&typeof body==='object'&&'useAI'in body&&body.useAI?(await authClient()?.auth.getSession())?.data.session?.access_token:undefined;const response=await fetch(url,{...(body?{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;}
 function download(name:string,content:string,type='text/plain'){if(!requireAccount())return;const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportTransactions(){const cell=(v:string)=>'"'+(/^[=+@\-\t\r]/.test(v)?"'":'')+v.replaceAll('"','""')+'"';download('afripay-demo-transactions.csv','DEMO DATA — NOT BLOCKCHAIN TRANSACTIONS\n'+['id,supplier,amount,asset,status,date',...data.payments.map(p=>[p.id,p.supplier,p.amount,p.asset,p.status,p.createdAt].map(cell).join(','))].join('\n'),'text/csv');}
 async function connectWallet(){setBusy(true);try{await mainWallet.connect();if(workspaceMode!=='live'){setWorkspaceMode('live');localStorage.setItem('afripay-view-mode','live');go('dashboard');}notify('Mainnet wallet connected. Review each payment before authorizing it in your wallet.');}catch(err){notify((err as Error).message||'Wallet connection was cancelled.');}finally{setBusy(false);}}
