 function loadSample(text:string,name:string){const example=seed().suppliers[0];setData(d=>({...d,suppliers:d.suppliers.some(item=>item.name===example.name)?d.suppliers:[...d.suppliers,example]}));setInvoiceText(text);setDraft(null);setUploadName(name);notify('Sample selected. An illustrative supplier record was loaded for this exercise. The invoice recipient still needs review.');}
 async function extract(text=invoiceText){if(!text.trim()){notify('Upload an invoice or paste its text first.');return;}setBusy(true);try{const result=await request('/api/extract',{text,useAI:ai});setDraft({...result.fields,id:uid(),status:'Needs review',verified:false,createdAt:new Date().toISOString()});notify('Fields extracted. Review each field and independently verify the recipient.');}catch(err){notify((err as Error).message);}finally{setBusy(false);}}
 async function upload(file?:File){if(!file)return;if(file.size>10*1024*1024){notify('Please choose an invoice smaller than 10 MB.');return;}setBusy(true);setUploadName(file.name);try{let text='';if(file.type==='application/pdf'){const pdfjs=await import('pdfjs-dist');pdfjs.GlobalWorkerOptions.workerSrc='/pdf.worker.min.mjs';const loadingTask=pdfjs.getDocument({data:await file.arrayBuffer()});const pdf=await loadingTask.promise;if(pdf.numPages>10)throw new Error('Please upload an invoice with 10 pages or fewer.');for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const content=await p.getTextContent();text+=content.items.map(item=>'str'in item?item.str:'').join('\n')+'\n';}await loadingTask.destroy();if(!text.trim())throw new Error('This PDF has no readable text. Upload an image for OCR, or paste the invoice text.');}else if(['image/png','image/jpeg','image/webp'].includes(file.type)){const {createWorker}=await import('tesseract.js');const worker=await createWorker('eng');try{const result=await worker.recognize(file);text=result.data.text;}finally{await worker.terminate();}}else if(file.type==='text/plain'||file.name.endsWith('.txt'))text=await file.text();else throw new Error('Supported formats: PDF, PNG, JPEG, WebP and TXT.');setInvoiceText(text);notify('Invoice text is ready. Select Extract fields to review it.');}catch(err){notify((err as Error).message);}finally{setBusy(false);}}
 function saveDraft(){if(!draft)return;if(!draft.number.trim()||!draft.supplier.trim()||!draft.amount||Number(draft.amount)<=0||!validAddress(draft.wallet,draft.chain)){notify('Enter an invoice number, supplier, positive amount and valid wallet.');return;}const risk=analyzeInvoice(draft,data.invoices,data.suppliers);const entry={...draft,risk,status:risk.level==='High'||risk.level==='Critical'?'Flagged' as const:draft.verified?'Ready to pay' as const:'Needs review' as const};setData(d=>({...d,invoices:[entry,...d.invoices.filter(i=>i.id!==entry.id)]}));recordRisk('Invoice '+draft.number,risk);setSelected(entry.id);setDraft(null);go('invoices/'+entry.id);notify('Invoice saved to your demo workspace.');}
 function viewInvoice(invoice:Invoice){setSelected(invoice.id);go('invoices/'+invoice.id);}
 const current=data.invoices.find(i=>i.id===(page.startsWith('invoices/')&&page!=='invoices/upload'?page.split('/')[1]:selected));
 function preparePayment(invoice?:Invoice){setSelectedCreditSupplier('');setCustomRecipient(false);if(!invoice)setPaymentForm(form=>({...form,invoiceId:''}));if(invoice){if(!invoice.verified){notify('Verify the supplier wallet before preparing payment.');return;}setPaymentForm({supplier:invoice.supplier,amount:invoice.amount,asset:invoice.currency,recipient:invoice.wallet,chain:invoice.chain,invoiceId:invoice.id});}setConfirmed(false);setReviewed(false);setLiveQuote(null);setQuoteTime(0);setQuoteMode('demo');go('payments');}
 function assessPayment(){return assessPaymentState(data,paymentForm);}
 function reviewRoutes(){const risk=assessPayment();setPaymentRisk(risk);recordRisk('Payment to '+paymentForm.supplier,risk);if(risk.blocked){notify('Payment blocked by Security Shield. Review the evidence.');return;}if(paymentForm.invoiceId&&!data.invoices.find(i=>i.id===paymentForm.invoiceId)?.verified){notify('Manually verify the invoice recipient before continuing.');return;}setQuoteTime(Date.now());setConfirmed(false);setReviewed(false);go('routes');}
 async function loadTokens(){setBusy(true);setApiError('');try{const result=await request('/api/tokens');setTokens(result.tokens);if(result.tokens.length){setOriginAsset(result.tokens.find((t:Token)=>t.blockchain==='near')?.assetId||result.tokens[0].assetId);setDestAsset(result.tokens.find((t:Token)=>t.blockchain===paymentForm.chain&&t.symbol==='USDC')?.assetId||result.tokens[0].assetId);}notify('Loaded supported tokens from NEAR Intents.');}catch(err){setApiError((err as Error).message);}finally{setBusy(false);}}
 async function fetchQuote(){setBusy(true);setApiError('');setLiveQuote(null);try{if(tokens.find(t=>t.assetId===destAsset)?.blockchain!==paymentForm.chain)throw new Error('Destination chain must match the verified payment recipient.');const result=await request('/api/quote',{dry:true,originAsset,destinationAsset:destAsset,amount:sourceAmount,recipient:paymentForm.recipient,refundTo:refund,slippageTolerance:Number(slippage)});setLiveQuote(result);setQuoteTime(Date.now());notify('Genuine dry quote received. No funds or deposit address requested.');}catch(err){setApiError((err as Error).message);}finally{setBusy(false);}}
 function submitDemo(){if(!requireAccount())return;
  const approval={confirmed,reviewed,quoteTime,quoteMode};const id=uid();
  try{approveDemoPayment(data,paymentForm,approval,id);}catch(err){setPaymentRisk(assessPayment());notify((err as Error).message);return;}
  setData(d=>{try{return approveDemoPayment(d,paymentForm,approval,id);}catch{return d;}});
  setConfirmed(false);go('monitor');notify('Simulation started. No blockchain transaction was signed or sent.');
 }
 function settle(p:Payment,outcome:'Settled (demo)'|'Failed (demo)'|'Refunded (demo)'){
  try{settleDemoPayment(data,p.id,outcome);}catch(err){notify((err as Error).message);return;}
  setData(d=>{try{return settleDemoPayment(d,p.id,outcome);}catch{return d;}});
  notify(outcome==='Settled (demo)'?'Simulated settlement confirmed. Demo receipt is ready.':outcome+' — invoice remains unpaid.');
 }

 async function analyzeTool(kind:'wallet'|'url'){setBusy(true);try{const result=await request('/api/analyze',{kind,value:toolInput,...(kind==='wallet'?{chain:toolChain}:{})});setToolResult(result);recordRisk(kind==='wallet'?'Wallet analysis':'Payment link analysis',result.risk);}catch(err){notify((err as Error).message);}finally{setBusy(false);}}
 async function sendMessage(e:React.FormEvent){e.preventDefault();if(!message.trim())return;const text=message;setMessage('');setChat(c=>[...c,{role:'user',text}]);setBusy(true);try{const result=await request('/api/assistant',{message:text,useAI:assistantAI});setChat(c=>[...c,{role:'assistant',text:result.message,structured:result.intent,provider:result.provider}]);if(result.intent.amount)setPaymentForm(f=>({...f,amount:result.intent.amount,asset:result.intent.asset||f.asset}));}catch(err){notify((err as Error).message);}finally{setBusy(false);}}
 async function authenticate(e:React.FormEvent){
  e.preventDefault();setAuthMessage('');setAuthMessageTone('red');setBusy(true);
  try{const auth=authClient();if(!auth)throw new Error('Account registration is not configured yet.');
   const signupDetails=authMode==='signup'?signupDetailsSchema.parse({full_name:signupName,account_type:signupType}):null;
   const result=authMode==='signin'?await auth.auth.signInWithPassword({email:authEmail.trim(),password:authPassword}):await auth.auth.signUp({email:authEmail.trim(),password:authPassword,options:{emailRedirectTo:location.origin+'/auth',data:signupDetails||{}}});
   if(result.error)throw result.error;
   if(authMode==='signup'&&signupOutcome(result.data)==='not-created'){setConfirmationEmail('');setAuthPassword('');setAuthMode('signin');setAuthMessage('This sign-up did not create a new account. If you have used this email before, sign in or choose Forgot your password. A new signup confirmation email is not guaranteed for an existing account.');return;}
   if(authMode==='signup'&&!result.data.session){setConfirmationEmail(authEmail.trim());setAuthPassword('');return;}
   if(result.data.session){setCheckOnboarding(true);setConfirmationEmail('');setAuthPassword('');notify(authMode==='signup'?'Account created and signed in.':'Signed in. Cloud save status appears above your dashboard.');go('dashboard');}
   else setAuthMessage('Sign-in did not create a session. Confirm your email, then try again.');
  }catch(err){setAuthMessage(err instanceof ZodError?err.issues[0].message:(err as Error).message);}finally{setBusy(false);}
 }
 function selectDirectorySupplier(supplier:DirectorySupplier){if(supplier.network){sessionStorage.removeItem('afripay-invoice-request');sessionStorage.setItem('afripay-supplier-payment:'+accountId,JSON.stringify({network:supplier.network,wallet:supplier.wallet,chain:supplier.chain,name:supplier.business_name}));sessionStorage.setItem('afripay-live-source','near');const mode=supplier.network==='mainnet'?'live':'testnet';setWorkspaceMode(mode);localStorage.setItem('afripay-view-mode',mode);go(mode==='testnet'?'transfer':'payments');notify('Supplier destination loaded for review. Confirm its network and address independently. Nothing has been sent.');return;}setSelectedCreditSupplier(supplier.id);changeMode('demo');setCustomRecipient(true);setPaymentForm({supplier:supplier.business_name,amount:'',asset:supplier.chain==='near'?'NEAR':'USDC',recipient:supplier.wallet,chain:supplier.chain,invoiceId:''});setPaymentRisk(null);go('payments');notify('Supplier loaded into a demo proposal. Review the recipient independently. No real funds will move.');}

 const totalPaid=data.payments.filter(p=>p.status==='Settled (demo)').reduce((s,p)=>s+Number(p.amount),0),pending=data.invoices.filter(i=>i.status!=='Paid (demo)').reduce((s,i)=>s+Number(i.amount),0),highRisk=data.events.filter(e=>['High','Critical'].includes(e.risk.level)).length;
