 const recentTransactions=(limit?:number)=><>{data.payments.length?<div className="table-wrap"><table><thead><tr><th>RECIPIENT</th><th>AMOUNT</th><th>ROUTE</th><th>STATUS</th><th>DATE</th><th/></tr></thead><tbody>{data.payments.slice(0,limit).map(p=><tr key={p.id}><td><div className="table-person"><span className="vendor-icon purple"><ArrowUpRight size={19}/></span><span><strong>{p.supplier}</strong><small>{p.id.slice(0,8)} · Demo</small></span></div></td><td><strong>{money(p.amount)}</strong><small>{p.asset}</small></td><td><span className="chain-pill">{p.chain}</span></td><td><Badge tone={p.status==='Settled (demo)'?'green':p.status.startsWith('Failed')?'red':'amber'}>{p.status}</Badge></td><td>{date(p.createdAt)}</td><td>{p.receipt?<button className="text-btn" disabled={busy} onClick={()=>receipt(p)}><Download size={15}/>Receipt</button>:<button className="text-btn" onClick={()=>go('monitor')}>Monitor <ArrowUpRight size={14}/></button>}</td></tr>)}</tbody></table></div>:<Empty icon={ArrowUpRight} title="Your first payment starts here" description="Pay a verified supplier and follow the journey from approval to receipt." action={<button className="btn secondary" onClick={()=>preparePayment()}>Create a demo payment <ArrowRight size={16}/></button>}/>}</>;
 async function receipt(p:Payment){if(!requireAccount())return;
  setBusy(true);
  try{
   const {createDemoReceipt}=await import('@/lib/receipt');
   const loadFont=async(name:string)=>{const response=await fetch('/fonts/'+name);if(!response.ok)throw new Error('Receipt fonts could not load. Please try again.');return new Uint8Array(await response.arrayBuffer());};
   const [regular,bold,mono]=await Promise.all(['DejaVuSans.ttf','DejaVuSans-Bold.ttf','DejaVuSansMono.ttf'].map(loadFont));
   const invoice=data.invoices.find(i=>i.id===p.invoiceId);
   const bytes=await createDemoReceipt(p,{business:identity.business,invoiceNumber:invoice?.number},{regular,bold,mono});
   const blob=new Blob([new Uint8Array(bytes)],{type:'application/pdf'});
   const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='AFRIPAY-Receipt-'+p.id.slice(0,8)+'.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
   notify('Your branded demo receipt PDF is ready.');
  }catch(err){notify((err as Error).message);}finally{setBusy(false);}
 }

